package com.emotiondiary.entity;
import jakarta.persistence.*;import lombok.*;import java.time.Instant;
@Entity @Getter @Setter @NoArgsConstructor public class JournalEntry{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private AppUser user; @Column(columnDefinition="text",nullable=false) private String text; private String selectedEmotion; private String detectedEmotion; private String finalEmotion; @Column(columnDefinition="text") private String analysis; @Column(columnDefinition="text") private String recommendation; private Instant createdAt; private Instant updatedAt; @PrePersist void pre(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void upd(){updatedAt=Instant.now();}}
